+.card-body {
+  padding: 1.25rem 1.5rem 1.5rem;
+  display: flex;
+  flex-wrap: wrap;
+  gap: 1.25rem;
+  align-items: flex-start;
+  justify-content: space-between;
+}
+.image-meta { flex: 1 1 200px; min-width: 0; }
+.image-title {
+  font-size: 1.0625rem;
+  font-weight: 600;
+  margin-bottom: .25rem;
+  overflow-wrap: anywhere;
