+  font-size: .8125rem;
+  color: var(--color-text-muted);
+  display: flex;
+  flex-wrap: wrap;
+  gap: .5rem .875rem;
+}
+.image-subtitle span { display: inline-flex; align-items: center; gap: .25rem; }
+
+.card-actions {
+  display: flex;
+  flex-wrap: wrap;
+  gap: .625rem;
+  flex-shrink: 0;
+}
+
