+.btn {
+  display: inline-flex;
+  align-items: center;
+  gap: .4375rem;
+  padding: .5625rem 1.0625rem;
+  border-radius: var(--radius-sm);
+  font-size: .875rem;
+  font-weight: 600;
+  line-height: 1;
+  border: 1.5px solid transparent;
+  cursor: pointer;
+  transition: background var(--transition), color var(--transition),
+              border-color var(--transition), box-shadow var(--transition);
+  white-space: nowrap;
+  text-decoration: none;
+}
+.btn:focus-visible {
+  outline: 3px solid var(--color-primary);
+  outline-offset: 2px;
+}
+
+.btn-secondary {
+  background: var(--color-surface);
+  color: var(--color-text);
+  border-color: var(--color-border);
+}
+.btn-secondary:hover {
+  background: var(--color-surface-alt);
+  border-color: #b0b0b8;
+}
+
+.btn-danger {
+  background: var(--color-danger-bg);
+  color: var(--color-danger);
+  border-color: #ffc0c5;
+}
+.btn-danger:hover {
+  background: #ffd6d9;
+  border-color: #f5a0a8;
+}
+.btn-danger:focus-visible { outline-color: var(--color-danger); }
+
+.btn-danger-solid {
+  background: var(--color-danger);
+  color: #fff;
+  border-color: var(--color-danger);
+}
+.btn-danger-solid:hover { background: var(--color-danger-dark); border-color: var(--color-danger-dark); }
+.btn-danger-solid:focus-visible { outline-color: var(--color-danger); }
+
+.btn-ghost {
+  background: transparent;
+  color: var(--color-text-muted);
+  border-color: transparent;
