+.dialog-title {
+  font-size: 1.1875rem;
+  font-weight: 700;
+  margin-bottom: .5rem;
+  letter-spacing: -.01em;
+}
+.dialog-desc {
+  font-size: .9375rem;
+  color: var(--color-text-muted);
+  line-height: 1.55;
+  margin-bottom: 1.5rem;
+}
+.dialog-image-name {
+  font-weight: 600;
+  color: var(--color-text);
+}
+
