+.dialog-footer {
+  display: flex;
+  gap: .75rem;
+  justify-content: flex-end;
+  flex-wrap: wrap;
+  border-top: 1px solid var(--color-border);
+  padding: 1rem 1.75rem 1.25rem;
+}
+
+/* close × button */
+.dialog-close {
+  position: absolute;
+  top: 1rem;
+  right: 1rem;
