+  height: 32px;
+  border-radius: 50%;
+  display: flex;
+  align-items: center;
+  justify-content: center;
+  padding: 0;
+}
+
+/* ── Live region ────────────────────────────────────────── */
+#status-message {
+  position: absolute;
+  width: 1px; height: 1px;
